import { execSync } from 'child_process';
import path from 'path';

// Creates a fresh test DB. The Prisma client is already generated by `npm ci` (postinstall),
// and regenerating it fails on Windows while a dev server holds the engine file open.
export default function setup() {
  const cwd = path.resolve(__dirname, '..');
  const env = { ...process.env, DATABASE_URL: 'file:./test.db' };
  execSync('npx prisma db push --force-reset --skip-generate', { cwd, env, stdio: 'inherit' });
}